import React, { useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import API from '../api';

const NoteForm = ({ isEdit = false }) => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    title: '',
    body: '',
    tags: '',
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Untuk edit, load data catatan
  React.useEffect(() => {
    if (isEdit) {
      setLoading(true);
      API.get(`/notes/${id}`)
        .then((res) => {
          const note = res.data.data.note;
          setFormData({
            title: note.title,
            body: note.body,
            tags: note.tags.join(','),
          });
          setLoading(false);
        })
        .catch((err) => {
          setError('Gagal memuat catatan');
          setLoading(false);
        });
    }
  }, [id, isEdit]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setLoading(true);
    
    const payload = {
      title: formData.title,
      body: formData.body,
      tags: formData.tags.split(',').map(tag => tag.trim()),
    };

    const apiCall = isEdit 
      ? API.put(`/notes/${id}`, payload)
      : API.post('/notes', payload);

    apiCall
      .then(() => {
        navigate('/');
      })
      .catch((err) => {
        setError('Gagal menyimpan catatan');
        setLoading(false);
      });
  };

  if (loading) return <div>Memuat...</div>;

  return (
    <form onSubmit={handleSubmit}>
      {error && <div style={{ color: 'red' }}>{error}</div>}
      
      <div>
        <label>Judul:</label>
        <input
          type="text"
          name="title"
          value={formData.title}
          onChange={handleChange}
          required
        />
      </div>
      
      <div>
        <label>Isi:</label>
        <textarea
          name="body"
          value={formData.body}
          onChange={handleChange}
          required
        />
      </div>
      
      <div>
        <label>Tag (pisahkan dengan koma):</label>
        <input
          type="text"
          name="tags"
          value={formData.tags}
          onChange={handleChange}
        />
      </div>
      
      <button type="submit" disabled={loading}>
        {isEdit ? 'Update Catatan' : 'Tambah Catatan'}
      </button>
      <button type="button" onClick={() => navigate('/')}>
        Batal
      </button>
    </form>
  );
};

export default NoteForm;
